import { Component, Host, h, Prop, Element, Fragment, type ComponentInterface } from '@stencil/core';
import { getDynamicSlots } from './utils';
import type { StepperOrientation, StepperItem } from './types';
import { noop } from 'lodash-es';

const prefix = 'stepper';

@Component({
  tag: 'ks-stepper',
  styleUrl: 'ks-stepper.scss',
  shadow: true,
})
export class KsStepper implements ComponentInterface {
  @Element() el!: HTMLKsStepperElement;

  /** Indicates whether the entire stepper is disabled, in addition to any per-item disabled states. */
  @Prop() disabled = false;
  /** The zero-based index of the current active step. This value controls which step is highlighted as active. */
  @Prop() current?: number = 0;
  /** The layout direction of the stepper. Use `vertical` to show each step's description content. */
  @Prop() orientation: StepperOrientation = 'horizontal';
  /** Indicates whether inactive step descriptions remain visible in vertical mode. */
  @Prop() showInactiveContent = false;
  /**
   * The step definitions to render.
   *
   * Each item can provide `title`, `description`, `icon`, and `disabled`. String values render directly, while render
   * functions are mapped to the corresponding indexed dynamic slots used internally by the component.
   */
  @Prop() items: StepperItem[] = [];

  private wrapWithSlot: (slotName: string, children: unknown) => unknown = noop;
  private setDynamicRenderDeps: (items: unknown[]) => void = noop;

  // FIXME buggy behavior in Vue
  componentWillRender() {
    // TODO do more edge case test for rerender
    const dynamicSlots = getDynamicSlots(this, this.wrapWithSlot);
    this.setDynamicRenderDeps(dynamicSlots);
  }

  private renderHorizontalStepper = () =>
    this.items.map((item, index) => {
      const disabled = this.disabled || item.disabled || false;
      const defaultIcon = `${index + 1}`.padStart(2, '0');

      return (
        <Fragment>
          <div
            class={{
              [`${prefix}__item`]: true,
              [`${prefix}__item--active`]: this.current === index,
              [`${prefix}__item--disabled`]: disabled,
            }}
            data-step-index={index}
          >
            <slot name={`icon-${index}`}>
              <span class={`${prefix}__item-header`}>{defaultIcon}</span>
            </slot>
            <div class={`${prefix}__item-label`}>
              {typeof item.title === 'string' ? item.title : <slot name={`title-${index}`} />}
            </div>
          </div>
          {index < this.items.length - 1 && <ks-divider class={`${prefix}__divider`} orientation="horizontal" />}
        </Fragment>
      );
    });

  private renderVerticalStepper = () =>
    this.items.map((item, index) => {
      const disabled = this.disabled || item.disabled || false;
      const defaultIcon = `${index + 1}`.padStart(2, '0');

      return (
        <div
          class={{
            [`${prefix}__item`]: true,
            [`${prefix}__item--active`]: this.current === index,
            [`${prefix}__item--disabled`]: disabled,
          }}
          data-step-index={index}
        >
          <div class={`${prefix}__item-header`}>
            <slot name={`icon-${index}`}>
              <span style={{ 'font-variant-numeric': 'lining-nums tabular-nums' }}>{defaultIcon}</span>
            </slot>
            {index < this.items.length - 1 && <ks-divider class={`${prefix}__divider`} orientation="vertical" />}
          </div>
          <div class={`${prefix}__item-container`}>
            <div class={`${prefix}__item-label`}>
              {typeof item.title === 'string' ? item.title : <slot name={`title-${index}`} />}
            </div>
            <div
              class={{
                [`${prefix}__item-content`]: true,
                [`${prefix}__item-content--active`]: this.current === index || this.showInactiveContent,
              }}
            >
              {typeof item.description === 'string' ? item.description : <slot name={`description-${index}`} />}
            </div>
          </div>
        </div>
      );
    });

  render() {
    const { orientation } = this;

    return (
      <Host class="KsStepper">
        <div class={`${prefix} ${prefix}--${orientation}`} aria-orientation={orientation}>
          {orientation === 'horizontal' ? this.renderHorizontalStepper() : this.renderVerticalStepper()}
        </div>
      </Host>
    );
  }
}
